import numpy as np

_N_SAMPLES = 5000
_SEED = 42
_rng_samples = np.random.default_rng(_SEED).uniform(0.0, 1.0, _N_SAMPLES)


def program(x) -> float:
    x = float(x)
    p = 1.0
    for t in _rng_samples:
        p *= x + t ** 2
    return float(p / _N_SAMPLES)
